def check_good_triple(x, y, z):
    """Checks if (x, y, z) is a good triple."""
    # The condition is that (x+1)^y / (x^z + 1) is a positive integer.
    # This means (x+1)^y must be divisible by (x^z + 1).

    try:
        numerator = (x + 1)**y
        denominator = x**z + 1

        # Check divisibility
        if denominator == 0:
            # This should not happen since x >= 1 and z >= 1, so x^z + 1 >= 2
            return False

        return numerator % denominator == 0
    except OverflowError:
        # Though Python handles large integers, this is a safeguard if extremely large numbers were involved.
        # Given x, y, z < 100, standard Python integers should suffice.
        return False

def count_good_triples(limit):
    """Counts the number of good triples (x, y, z) where 1 <= x, y, z < limit."""
    count = 0
    # Since the problem states 0 < x, y, z < 100, the limit is 100.
    for x in range(1, limit):
        for y in range(1, limit):
            for z in range(1, limit):
                if check_good_triple(x, y, z):
                    count += 1
    return count

LIMIT = 100
count = count_good_triples(LIMIT)
print(f"Total number of good triples (0 < x, y, z < 100): {count}")

